CREATE TABLE public.service_providers (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, api_url text NOT NULL, api_key text NOT NULL, active boolean NOT NULL DEFAULT false, markup numeric NOT NULL DEFAULT 0 CHECK(markup BETWEEN 0 AND 10000), link_parameter text NOT NULL DEFAULT 'link' CHECK(link_parameter IN ('link','url')), last_synced_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), deleted_at timestamptz);
GRANT ALL ON public.service_providers TO service_role;
ALTER TABLE public.service_providers ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.service_source_settings (id integer PRIMARY KEY CHECK(id=1), own_enabled boolean NOT NULL DEFAULT true, api_enabled boolean NOT NULL DEFAULT true);
GRANT ALL ON public.service_source_settings TO service_role;
ALTER TABLE public.service_source_settings ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.services ADD COLUMN provider_id uuid REFERENCES public.service_providers(id), ADD COLUMN provider_service_id text, ADD COLUMN provider_rate numeric, ADD COLUMN provider_available boolean NOT NULL DEFAULT true, ADD COLUMN custom_name boolean NOT NULL DEFAULT false, ADD COLUMN custom_rate boolean NOT NULL DEFAULT false;
CREATE UNIQUE INDEX services_provider_reference ON public.services(provider_id,provider_service_id) WHERE provider_id IS NOT NULL;
ALTER TABLE public.orders ADD COLUMN provider_id uuid REFERENCES public.service_providers(id), ADD COLUMN provider_service_id text, ADD COLUMN provider_order_id text, ADD COLUMN dispatch_state text NOT NULL DEFAULT 'manual', ADD COLUMN provider_error text;
CREATE FUNCTION public.service_source_enabled(_provider uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT CASE WHEN _provider IS NULL THEN coalesce((SELECT own_enabled FROM public.service_source_settings WHERE id=1),true) ELSE coalesce((SELECT api_enabled FROM public.service_source_settings WHERE id=1),true) AND EXISTS(SELECT 1 FROM public.service_providers WHERE id=_provider AND active AND deleted_at IS NULL) END $$;
GRANT EXECUTE ON FUNCTION public.service_source_enabled(uuid) TO anon,authenticated,service_role;
ALTER POLICY "public services" ON public.services USING (active AND deleted_at IS NULL AND provider_available AND public.service_source_enabled(provider_id));
CREATE FUNCTION public.validate_service_source_order() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE _s public.services; BEGIN SELECT * INTO _s FROM public.services WHERE id=NEW.service_id; IF NOT public.service_source_enabled(_s.provider_id) OR NOT _s.provider_available THEN RAISE EXCEPTION 'SERVICE_UNAVAILABLE'; END IF; NEW.provider_id:=_s.provider_id; NEW.provider_service_id:=_s.provider_service_id; IF _s.provider_id IS NOT NULL THEN NEW.dispatch_state:='queued'; END IF; RETURN NEW; END $$;
CREATE TRIGGER validate_service_source_order BEFORE INSERT ON public.orders FOR EACH ROW EXECUTE FUNCTION public.validate_service_source_order();
CREATE OR REPLACE FUNCTION public.cancel_my_order(_order_id uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE _o public.orders; _newbal numeric; BEGIN SELECT * INTO _o FROM public.orders WHERE id=_order_id AND user_id=auth.uid() FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'NOT_FOUND'; END IF; IF _o.status <> 'pending' OR _o.provider_id IS NOT NULL THEN RAISE EXCEPTION 'CANNOT_CANCEL'; END IF; UPDATE public.profiles SET balance=balance+_o.charge WHERE id=_o.user_id RETURNING balance INTO _newbal; UPDATE public.orders SET status='canceled',refunded=_o.charge,updated_at=now() WHERE id=_o.id; INSERT INTO public.wallet_ledger(user_id,amount,kind,ref,balance_after) VALUES(_o.user_id,_o.charge,'refund',_o.order_code,_newbal); END $$;
CREATE FUNCTION public.sync_provider_catalog(_provider uuid,_rows jsonb) RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE _p public.service_providers; _r jsonb; _platform uuid; _cat uuid; _slug text; _name text; _count integer:=0; BEGIN SELECT * INTO _p FROM public.service_providers WHERE id=_provider AND deleted_at IS NULL FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'NOT_FOUND'; END IF; UPDATE public.services SET provider_available=false WHERE provider_id=_provider; FOR _r IN SELECT value FROM jsonb_array_elements(_rows) LOOP _slug:=_r->>'platform'; _name:=_r->>'platform_name'; SELECT id INTO _platform FROM public.platforms WHERE slug=_slug; IF _platform IS NULL THEN INSERT INTO public.platforms(slug,name,active) VALUES(_slug,_name,true) RETURNING id INTO _platform; END IF; SELECT id INTO _cat FROM public.categories WHERE platform_id=_platform AND name=_r->>'category' AND deleted_at IS NULL ORDER BY sort LIMIT 1; IF _cat IS NULL THEN INSERT INTO public.categories(platform_id,name,active) VALUES(_platform,_r->>'category',true) RETURNING id INTO _cat; END IF; INSERT INTO public.services(category_id,name,rate,rate_per,min_qty,max_qty,provider_id,provider_service_id,provider_rate,provider_available) VALUES(_cat,left(_r->>'name',200),ceil((_r->>'rate')::numeric*(1+_p.markup/100)*10000)/10000,1000,(_r->>'min')::integer,(_r->>'max')::integer,_provider,_r->>'service',(_r->>'rate')::numeric,true) ON CONFLICT(provider_id,provider_service_id) WHERE provider_id IS NOT NULL DO UPDATE SET name=CASE WHEN services.custom_name THEN services.name ELSE EXCLUDED.name END,rate=CASE WHEN services.custom_rate THEN services.rate ELSE EXCLUDED.rate END,provider_rate=EXCLUDED.provider_rate,min_qty=EXCLUDED.min_qty,max_qty=EXCLUDED.max_qty,provider_available=true; _count:=_count+1; END LOOP; UPDATE public.service_providers SET last_synced_at=now() WHERE id=_provider; UPDATE public.site_settings SET content_version=content_version+1 WHERE id=1; RETURN _count; END $$;
REVOKE ALL ON FUNCTION public.sync_provider_catalog(uuid,jsonb) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.sync_provider_catalog(uuid,jsonb) TO service_role;
CREATE FUNCTION public.set_provider_markup(_provider uuid,_markup numeric) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF _markup<0 OR _markup>10000 THEN RAISE EXCEPTION 'INVALID_MARKUP'; END IF; UPDATE public.service_providers SET markup=_markup WHERE id=_provider; UPDATE public.services SET rate=ceil(provider_rate*(1+_markup/100)*10000)/10000,custom_rate=false WHERE provider_id=_provider AND deleted_at IS NULL; UPDATE public.site_settings SET content_version=content_version+1 WHERE id=1; END $$;
REVOKE ALL ON FUNCTION public.set_provider_markup(uuid,numeric) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.set_provider_markup(uuid,numeric) TO service_role;